const e={model:"gemma4:12b",digest:"4eb23ef187e2c5462566d6a1d3bbbc2f1346d0b4327cbb66d58fffbcc9b2b05c",promptVersion:3,date:"2026-08-30",status:{"ni.character.awareness.why":"reviewed","ni.character.control.why":"reviewed","ni.character.endurance.why":"reviewed","ni.character.precision.why":"reviewed","ni.character.speed.why":"reviewed","ni.energy.recovery.auxiliary":"reviewed","ni.energy.recovery.dominant":"reviewed","ni.energy.recovery.inferior":"reviewed","ni.energy.recovery.shadow":"reviewed","ni.energy.recovery.tertiary":"reviewed","ni.feeder.fe":"reviewed","ni.feeder.fi":"reviewed","ni.feeder.se":"reviewed","ni.feeder.te":"reviewed","ni.feeder.ti":"reviewed","ni.fieldNotes.mirror":"reviewed","ni.fieldNotes.vignette.brainstorm":"reviewed","ni.fieldNotes.vignette.cantJustKnow":"reviewed","ni.fieldNotes.vignette.grip":"reviewed","ni.fieldNotes.vignette.loop":"reviewed","ni.fieldNotes.vignette.mechanicsHunch":"reviewed","ni.fieldNotes.vignette.meeting":"reviewed","ni.fieldNotes.vignette.mistakenForSi":"reviewed","ni.hero.heading":"reviewed","ni.hero.subtitle":"reviewed","ni.hero.tag":"reviewed","ni.lab.btn.aha.label":"reviewed","ni.lab.btn.aha.sub":"reviewed","ni.lab.btn.cassandra.label":"reviewed","ni.lab.btn.cassandra.sub":"reviewed","ni.lab.btn.flash.label":"reviewed","ni.lab.btn.flash.sub":"reviewed","ni.lab.btn.focus.label":"reviewed","ni.lab.btn.focus.sub":"reviewed","ni.lab.btn.overfit.label":"reviewed","ni.lab.btn.overfit.sub":"reviewed","ni.lab.meter.pleasure":"reviewed","ni.lab.meter.stress":"reviewed","ni.lab.narration.aha":"reviewed","ni.lab.narration.aha2":"reviewed","ni.lab.narration.cassandra":"reviewed","ni.lab.narration.cassandra2":"reviewed","ni.lab.narration.flash":"reviewed","ni.lab.narration.flash2":"reviewed","ni.lab.narration.focus":"reviewed","ni.lab.narration.focus2":"reviewed","ni.lab.narration.hover":"reviewed","ni.lab.narration.intro":"reviewed","ni.lab.narration.introHintCoarse":"reviewed","ni.lab.narration.introHintFine":"reviewed","ni.lab.narration.overfit":"reviewed","ni.lab.narration.overfit2":"reviewed","ni.lab.state.cynical":"reviewed","ni.lab.state.equilibrium":"reviewed","ni.lab.state.euphoric":"reviewed","ni.lab.state.freeze":"reviewed","ni.lab.state.overfit":"reviewed","ni.lab.telemetry.cogState":"reviewed","ni.lab.telemetry.conf":"reviewed","ni.lab.telemetry.loss":"reviewed","ni.meta.title":"reviewed","ni.slot.auxiliary":"reviewed","ni.slot.critical":"reviewed","ni.slot.demon":"reviewed","ni.slot.dominant":"reviewed","ni.slot.inferior":"reviewed","ni.slot.opposing":"reviewed","ni.slot.tertiary":"reviewed","ni.slot.trickster":"reviewed","ni.zoneA.canvasAria":"reviewed","ni.zoneB.heading":"reviewed","ni.zoneB.lede":"reviewed","ni.zoneB.railAria":"reviewed","ni.zoneC.heading":"reviewed","ni.zoneC.lede":"reviewed","ni.zoneC.unstableDefault":"reviewed","ni.zoneD.canvasAria":"reviewed","ni.zoneD.heading":"reviewed","ni.zoneD.kicker":"reviewed","ni.zoneD.lede":"reviewed","ni.zoneD.ledeHintCoarse":"reviewed","ni.zoneD.ledeHintFine":"reviewed","ni.zoneE.lede":"reviewed"}},n={_meta:e,"ni.character.awareness.why":"certaine de sa forme, incapable de montrer son travail","ni.character.control.why":"les intuitions arrivent selon leur propre calendrier ; le gouvernail répond lentement","ni.character.endurance.why":"la convergence est patiente — l'entonnoir fonctionne pendant des heures sans effort","ni.character.precision.why":"une trajectoire, ajustée étroitement ; l'enveloppe se rétrécit à mesure qu'elle s'exécute","ni.character.speed.why":"la convergence attend le moment opportun — l'intuition arrive entière, et tard","ni.energy.recovery.auxiliary":"Récupération propre une fois que la lecture a été transmise à quelqu'un.","ni.energy.recovery.dominant":"Se recharge partiellement pendant l'utilisation — chaque intuition qui s'ancre rend un peu d'énergie.","ni.energy.recovery.inferior":"L'étagère de la gueule de bois : ~30 min où tout le système fonctionne faiblement et où la lecture du destin continue de se répéter.","ni.energy.recovery.shadow":"Incomplet — une partie de la charge ne revient tout simplement pas aujourd'hui.","ni.energy.recovery.tertiary":"Plus lent : la traque des schémas doit d'abord être réellement abandonnée.","ni.feeder.fe":{figure:"Plusieurs canaux souples alimentant une ligne de patient.",mechanism:"Fe — sentiment extraverti — renvoie l'état de la pièce : ce qui se passe entre ces personnes en particulier et ce qu'elles sont susceptibles d'en faire. Plus de canaux, des entrées plus petites, une image des trajectoires de relation. La correction arrive socialement — plus lente qu'un nombre, et plus difficile à écarter.",pair:"le couplage INFJ · ENFJ",provenance:"myers"},"ni.feeder.fi":{figure:"La ligne s'assombrit sans bouger.",mechanism:"La boucle INTJ, avec Te retiré : Fi — sentiment introverti — fournit le jugement, aussi de l'intérieur, pesant l'image par rapport à ce qui importe à une personne et rien d'autre. Sans air et auto-confirmateur : une lecture de la manière dont tout cela se déroule qui devient plus certaine plus personne à l'extérieur ne la touche, et pas plus précise.",pair:"la boucle Ni–Fi de l'INTJ",provenance:"community",warn:"Couplage en boucle : jugement introverti alimentant la perception introvertie — aucune correction extérieure."},"ni.feeder.se":{figure:"Les fragments arrivent plus vite qu'ils ne peuvent être retenus ; l'image se forme presque mais s'échappe aussitôt.",mechanism:"Se — sensation extravertie — inonde l'entrée avec le présent : dense, concret, immédiat, tout est vrai et rien n'est dirigé ailleurs, tandis que rien ne trie quoi que ce soit — les deux fonctions collectent et aucune ne juge. Ces deux fonctions siègent également sur le même axe : ce que l'une prend comme évident, l'autre le traite comme du bruit. Les piles réelles alternent perception et jugement pour cette raison précise.",pair:"La perception alimente la perception",provenance:"myers",warn:"Couplage instable : une perception alimentatrice d'une autre, sans jugement de l'une ou de l'autre."},"ni.feeder.te":{figure:"Un flux mince et ciblé ; l'enveloppe se resserre là où les nombres atterrissent.",mechanism:"Te — pensée extravertie — rend les résultats, les mesures et l'état du plan : peu d'entrées, chacune difficile, chacune sur un canal ciblé étroit. L'image qui se forme concerne la manière dont une structure évolue sur des années, et elle est corrigée quand les chiffres divergent. La correction d'erreur la plus directe et la plus fiable de Ni.",pair:"le couplage INTJ · ENTJ",provenance:"myers"},"ni.feeder.ti":{figure:"La frontière scelle un tour supplémentaire ; remarquez à quel point l'ajustement s'active précocement dans cet état.",mechanism:"La boucle INFJ, avec Fe retiré : Ti — pensée introvertie — fournit le jugement, mais de l'intérieur. L'image est vérifiée pour sa cohérence interne et jamais par rapport à quoi que ce soit dans la pièce, donc la convergence devient plus rapide et la certitude plus étroite — et la seule chose corrigeant l'image est la même tête qui l'a produite.",pair:"la boucle Ni–Ti de l'INFJ",provenance:"community",warn:"Couplage en boucle : jugement introverti alimentant la perception introvertie — aucune correction extérieure."},"ni.fieldNotes.mirror":{figure:"Deux entonnoirs, bouche contre bouche.",mechanismHtml:"Même élément, attitude opposée — et la différence est le sens vers lequel le cône pointe. <strong>Ne</strong> prend une entrée et la déploie en plusieurs futurs, tous vivants à la fois, tous peu coûteux à tenir, aucun d'entre eux choisi. <strong>Ni</strong> prend plusieurs entrées et les canalise en une seule, et celle-ci arrive entière, coûteuse à changer, et impossible à montrer. Ne échange l'engagement pour l'étendue ; Ni échange l'étendue pour une conviction qu'elle ne peut sourcer.",provenance:"jung"},"ni.fieldNotes.vignette.brainstorm":{figure:"Un entonnoir ne peut pas fonctionner comme un arroseur.",kind:"l'instrument erroné",mechanism:"Demandez à Ni vingt options rapides et regardez l'instrument refuser la spécification : il restera silencieux à travers la rafale de post-it et finira par offrir une option, tardive, entièrement formée, avec l'argument pour elle soudé. La convergence qui la rend précieuse est exactement ce qui la rend incorrecte ici. Les équipes qui le savent cessent d'évaluer Ni sur le volume et commencent à lui donner la liste restreinte à la place.",provenance:"community",title:"Le Brainstorming"},"ni.fieldNotes.vignette.cantJustKnow":{figure:"Un instrument qui ne peut pas imprimer ses données brutes.",kind:"l'accusation",mechanism:"L'accusation traite une dérivation manquante comme une base manquante. Ce qui manque réellement est une interface : l'entonnoir a consommé des centaines d'observations et n'a renvoyé que la destination, et les étapes intermédiaires n'ont jamais été stockées nulle part de récupérable. La réponse correcte à une lecture Ni n'est ni la foi ni le rejet — c'est la traiter comme une mesure d'un instrument qui ne peut pas montrer son travail, et la tester comme toute autre mesure.",provenance:"currents",title:"On ne peut pas savoir ça comme ça"},"ni.fieldNotes.vignette.grip":{figure:"L'horizon se resserre à portée de bras.",kind:"l'emprise",mechanism:"Un INTJ ayant épuisé ses réserves cesse de voir où les choses mènent et sombre dans la fonction inférieure Se — achetant des choses, conduisant trop vite, mangeant et buvant sans s'en rendre compte, sollicitant le corps jusqu'à ce qu'il soit la seule chose dans la pièce. Pas un changement de personnalité : un siège à faible capacité recevant un flux de taille dominante.",provenance:"quenk",title:"L'emprise"},"ni.fieldNotes.vignette.loop":{figure:"Scellé, élaboré, certain.",kind:"la boucle",mechanism:"Sous l'effet du stress, la Ni dominante d'un INFJ s'associe à la Ti tertiaire — toutes deux tournées vers l'intérieur, avec le contact de Fe avec les gens réels coupé entre elles. La lecture devient plus élaborée, plus cohérente en interne et plus certaine, et personne à l'extérieur de cette tête ne l'a touchée depuis des semaines. Ce schéma de même direction est appelé une boucle.",provenance:"community",title:"La boucle"},"ni.fieldNotes.vignette.mechanicsHunch":{figure:"Prévoyance à bande étroite, mains calleuses.",kind:"en tant que tertiaire",mechanism:"Ni tertiaire chez un ISTP ou ISFP : un moteur de convergence discret sous un extérieur pratique. Elle se manifeste comme le mécanicien qui s'arrête en plein travail parce que la panne « ne sera pas l'alternateur », le grimpeur qui change de route pour une raison qui arrive comme une certitude avant d'arriver comme une météo. Une prévoyance à bande étroite, proche du corps — fiable pour les machines et le terrain, et rarement invitée à donner son avis sur autre chose.",provenance:"grant",title:"L'intuition du mécanicien"},"ni.fieldNotes.vignette.meeting":{figure:"L'entonnoir n'a renvoyé que la destination.",kind:"type de rencontre",mechanism:"Dix minutes après, une personne avec Ni dominante sait comment le projet se termine et le dit. Demandée pourquoi, elle produit une raison qui est vraie mais qui n'est pas la raison — c'est la chose la plus proche disable d'une lecture qui n'a jamais eu d'étapes. Six mois plus tard, elle s'avère avoir raison, ce qui ne fait rien pour améliorer la prochaine explication.",provenance:"community",title:"La Réunion"},"ni.fieldNotes.vignette.mistakenForSi":{figure:"Le registre contre le vecteur.",kind:"la lecture erronée",mechanism:`Les deux sont calmes, prudents et intérieurs, donc les deux perceveurs introvertis sont confondus — généralement comme des "gens du détail". L'indice est ce que "comment le sais-tu ?" récupère. Si produit le registre : la date, le précédent, les trois dernières fois que cette chose exacte est arrivée. Ni produit la forme : vers quoi cela se dirige, dépouillé de chaque particularité qui a construit la trajectoire. L'un archive le passé en pleine résolution ; l'autre le comprime au-delà de toute récupération.`,provenance:"community",title:"Confondu avec Si"},"ni.hero.heading":"La convergence de {fn}","ni.hero.subtitle":"Un champ d'observations éparses, une trajectoire ajustée à travers elles — et une construction unique parcourant la ligne à travers le temps, déjà certaine de l'endroit où elle bifurque.","ni.hero.tag":"intuition introvertie","ni.lab.btn.aha.label":"Aha ! Synthèse","ni.lab.btn.aha.sub":"injecter des données disparates → synthétiser un paradigme","ni.lab.btn.cassandra.label":"La tragédie de Cassandra","ni.lab.btn.cassandra.sub":"prévision ignorée → échec prédit","ni.lab.btn.flash.label":"Interruption Tactique Flash","ni.lab.btn.flash.sub":"passez à l'action maintenant !","ni.lab.btn.focus.label":"Simulation de concentration profonde","ni.lab.btn.focus.sub":"entrer dans un bloc de concentration profonde et ininterrompue","ni.lab.btn.overfit.label":"Surapprentissage par microgestion","ni.lab.btn.overfit.sub":"forcer le formatage granulaire du tableur","ni.lab.meter.pleasure":"Plaisir","ni.lab.meter.stress":"Stress","ni.lab.narration.aha":{figure:"Les résidus s'effondrent et l'enveloppe de variance se resserre.",mechanism:"Deux douzines d'observations sans lien entre elles — et pour un instant, elles n'en ont pas. Puis une trajectoire fait l'affirmation de chaque exception à la fois, et ce qui était un nuage devient soudainement une ligne avec une direction. Notez l'ordre des événements : la réponse est arrivée, et elle est alors devenue évidente.",provenance:"currents"},"ni.lab.narration.aha2":{figure:"R² proche de l'unité, perte proche de zéro, stress disparu.",mechanism:"C'est la rémunération pour laquelle Ni travaille — pas les éloges, pas les résultats : la compression. Vingt choses sont devenues une chose, et cette chose unique prédit. Les valeurs aberrantes qui l'ont produite sont déjà indiscernables de la ligne qu'elles ont rejointe.",provenance:"currents"},"ni.lab.narration.cassandra":{figure:"Observez la construction arriver au passage qu'elle a nommé à l'avance.",mechanism:"Le modèle a vu cela. La lecture a traversé la limite de défaillance depuis un certain temps, et le dire à voix haute n'a rien changé.",provenance:"currents"},"ni.lab.narration.cassandra2":{figure:"L'affichage du niveau de confiance ne bougeait jamais.",mechanism:"Échec, comme prévu. L'ajustement était précis tout le temps — ce qui est la cruauté spécifique ici : avoir raison tôt est indiscernable, de l'extérieur, d'avoir tort jusqu'au moment où cela cesse de l'être. La légère et amère hausse sur le cadran du plaisir est réelle, et ce n'est pas une sensation agréable.",provenance:"currents"},"ni.lab.narration.flash":{figure:"La trajectoire se brise en un bruit à haute fréquence alors que le présent assaille le champ de vision.",mechanism:`"Faites le choix maintenant." La seule ressource sur laquelle cette fonction s'appuie — le temps pour simuler — vient d'être révoquée. Elle n'a pas de réponse rapide ; elle a une réponse en mémoire tampon, et le tampon a reçu l'ordre de s'arrêter.`,provenance:"currents"},"ni.lab.narration.flash2":{figure:"La ligne se réassemble à partir d'un ajustement inférieur.",mechanism:"Le barrage passe et le réajustement commence à partir d'un R² abattu. Rien n'a été appris pendant l'interruption ; le temps sous le feu n'est pas une donnée, juste du temps. Ce qu'une échéance achète de la part de Ni n'est pas la vitesse — c'est la supposition qui traînait à portée de main quand l'horloge a atteint zéro.",provenance:"currents"},"ni.lab.narration.focus":{figure:"La trajectoire s'étend en douceur au-delà du bord du champ de vision.",mechanism:"La porte se ferme et l'entrée s'arrête — non résolue, simplement plus d'entrées. La projection s'étend : un pas au-delà de maintenant, puis un autre, avec l'incertitude à peine élargie. C'est la machine faisant ce pour quoi elle est tarifée, à la profondeur pour laquelle elle est tarifée.",provenance:"currents"},"ni.lab.narration.focus2":{figure:"Mêmes points, ligne plus longue.",mechanism:"Notez ce que la concentration profonde n'a pas fait : elle n'a ajouté aucune donnée. La prévoyance s'est prolongée sur les mêmes observations, car la simulation ininterrompue est la manière dont cette fonction convertit le matériel détenu en portée. La mise à niveau la moins chère que Ni reçoive est une porte fermée.",provenance:"currents"},"ni.lab.narration.hover":"Vous tenez la barre. À gauche, c'est plus tôt, à droite, c'est plus tard — et la composition de la construction à chaque point est ce que le modèle estime que le concept prend cette forme. Remarquez qu'il s'agit du même objet tout au long du parcours : un développement, pas un remplacement.","ni.lab.narration.intro":"Le moteur tourne sans surveillance : les observations s'accumulent, une trajectoire s'y ajuste, et la construction parcourt la ligne d'une extrémité du temps à l'autre, se transformant au fil de son chemin.","ni.lab.narration.introHintCoarse":"Appuyez et faites glisser de gauche à droite dans la chambre pour prendre le gouvernail vous-même — ou perturbez le moteur en dessous et regardez la télémétrie réagir.","ni.lab.narration.introHintFine":"Survolez la chambre pour prendre la barre vous-même — ou perturbez le moteur en dessous et regardez la télémétrie réagir.","ni.lab.narration.overfit":{figure:"La ligne de tendance passe par chaque point de bruit individuellement ; la lecture de l'horizon affiche zéro étape en avant.",mechanism:"Chaque cellule formatée, chaque variation locale respectée. La précision sur ce qui s'est déjà produit est spectaculaire — et l'extrapolation est médiocre : le modèle a mémorisé les résidus et oublié la direction.",provenance:"currents"},"ni.lab.narration.overfit2":{figure:"La construction tremble pour respecter les décimales.",mechanism:"C'est ce que le micro-management coûte à un instrument à longue portée : la généralité. Forcée à rendre compte de chaque cellule, elle ne peut plus dire où tout va — précision sur le présent, achetée au prix du futur.",provenance:"currents"},"ni.lab.state.cynical":"Résignation cynique","ni.lab.state.equilibrium":"Équilibre optimal","ni.lab.state.euphoric":"Flux euphorique","ni.lab.state.freeze":"Submersion / Blocage","ni.lab.state.overfit":"Fatigue par surapprentissage","ni.lab.telemetry.cogState":"État cognitif","ni.lab.telemetry.conf":"Confiance de prédiction","ni.lab.telemetry.loss":"Perte du modèle","ni.meta.title":"Ni — Intuition Introvertie · CURRENTS","ni.slot.auxiliary":{example:"Le plan à cinq ans d'un ENTJ contient une phrase de pure prévoyance ; le reste est de l'exécution.",figure:"Un entonnoir aux quatre cinquièmes, alimentant une machine qui expédie.",mechanism:"Dans le siège secondaire, la lecture longue sert quelque chose déjà en cours : elle fournit une direction plutôt qu'une identité, et la fonction de jugement dominante la convertit en un plan ou une chambre gérée. Plus rapide à énoncer, plus facile à contester, et bien moins susceptible de rester sur une seule image pendant une décennie.",provenance:"myers"},"ni.slot.critical":{example:"Un INFP conclut à minuit que le schéma de toute sa vie est désormais visible, et il n'est pas bon.",figure:"Une ligne grise à travers le soi, s'étendant jusqu'à l'horizon.",mechanism:"Dans le siège six, la prévoyance se tourne vers l'intérieur et rend des verdicts sur sa propre vie — voici ce que vous êtes, voici où cela s'arrête — total, sans source, et destiné à personne d'autre. Elle prévoit bien plus avec assurance qu'elle ne vérifie.",provenance:"beebe"},"ni.slot.demon":{example:"Un ISFJ sait, lors d'une terrible soirée, exactement comment chacun de ceux qu'il aime va partir.",figure:"Une ligne unique, tracée en noir, traversant chaque point à la fois.",mechanism:"Le huitième siège est le plus rare et le pire. Lorsqu'il y a une éruption, il produit une certitude noire sur la façon dont tout cela se termine — appliquée à tout à la fois, immunisée contre les preuves, et indifférente au fait que la version d'hier disait quelque chose de différent. C'est le siège le moins pratiqué dans la pile, pas une prophétie.",provenance:"beebe"},"ni.slot.dominant":{example:"Dix minutes après le coup d'envoi, un INFJ sait comment le projet se termine — et met six mois à avoir raison de manière prouvable.",figure:"CURRENTS dessine ceci comme une régression à pleine profondeur : une enveloppe serrée, un ajustement sans hâte.",mechanism:"Dans le premier siège, tout est lu selon sa direction, et la lecture s'exécute continuellement, invisiblement, à faible coût. De longues périodes passent durant lesquelles rien de lisible ne se produit ; puis une réponse arrive entière, déjà certaine. Montrer les étapes est véritablement difficile — les étapes n'ont jamais été détenues séparément.",provenance:"myers"},"ni.slot.inferior":{example:"Un ESTP qui ne regarde jamais au-delà de ce soir se réveille à 4h du matin, certain que l'entreprise est condamnée, en détail.",figure:"Un entonnoir sombre qui tire rarement, et toujours vers le même point sombre.",mechanism:"Dans le siège tertiaire, le futur arrive comme un verdict plutôt qu'une prévision. De longues périodes de vie au présent sont ponctuées — sous la fatigue ou le stress — par une certitude totale soudaine que cela finit mal, a toujours dû mal finir, et n'est pas ouvert à la discussion, dans un registre qui ne leur ressemble pas. C'est l'emprise de Quenk.",provenance:"quenk"},"ni.slot.opposing":{example:"Affirmant que le marché ne va que dans un seul sens, un ENFP narre instantanément le krach — puis commande un dessert.",figure:"Sous la ligne de flottaison, une contre-trajectoire tracée d'un seul trait et abandonnée.",mechanism:"Le cinquième siège ouvre l'ombre — les quatre positions qu'une personne exécute rarement, et surtout sans s'en apercevoir. Ici, la lecture longue éveille le combat : quand la vision unique du futur d'un autre commence à réduire les options, une certitude rivale apparaît — plus sombre, plus inévitable, et maintenue exactement assez longtemps pour refuser la première.",provenance:"beebe"},"ni.slot.tertiary":{example:"Le mécanicien s'arrête en plein travail : « ce n'est pas l'alternateur. » Ce n'est pas le cas.",figure:"Un entonnoir de taille moyenne qui se focalise, puis erre.",mechanism:"Dans le siège tertiaire, la lecture de schémas arrive par accès et est acceptée de manière inégale : un sentiment soudain et clair de la façon dont une situation se déroule — généralement cohérent, parfois une histoire entière bâtie sur rien — avec peu d'intérêt à défendre l'un ou l'autre. Elle se stabilise avec l'âge, principalement en apprenant lesquelles de ses propres intuitions vérifier.",provenance:"grant"},"ni.slot.trickster":{example:"Un ESTJ ne perçoit pas la lettre de démission entre les lignes, puis découvre une conspiration dans le plan de table.",figure:"L'enveloppe ne se rétrécit jamais ; l'ajustement se pose à côté des points.",mechanism:"Dans le siège sept, l'implication est un jeu truqué : soit rien n'est entre les lignes, soit tout l'est. Le siège alterne entre un sous-texte manquant qui était pourtant là et la construction d'un sous-texte élaboré que personne n'avait voulu — sans malice, et généralement sans remarquer ce qu'il vient de faire.",provenance:"beebe"},"ni.zoneA.canvasAria":"Représentation visuelle interactive de l'Intuition Introvertie en tant que moteur de régression : des observations éparses convergent vers une trajectoire ajustée avec une enveloppe de confiance, et une construction synthétisée suit la ligne à travers le temps, se métamorphosant au fur et à mesure. Cliquez ou faites glisser à travers la chambre pour diriger la construction le long de l'axe du temps.","ni.zoneB.heading":"Les huit visages de Ni","ni.zoneB.lede":"Le canevas dépeint Ni comme une régression : de nombreuses observations entrant, une trajectoire ajustée sortant. La position de Ni dans la pile d'une personne — l'ordre fixe dans lequel ses huit fonctions apparaissent — modifie le comportement de la lecture. Cliquez sur une position pour voir le changement, du cône sans hâte de la dominante à la certitude noire unique de l'ombre, et observez le relevé de convergence : il raconte l'histoire avant la légende. Faites glisser le curseur de maturité pour voir les sièges inférieurs gagner en fidélité avec l'âge.","ni.zoneB.railAria":"Positions de la pile pour Ni","ni.zoneC.heading":"Qu'alimente Ni ?","ni.zoneC.lede":"Ni rassemble ; elle ne juge pas. La perception introvertie est alimentée par le jugement extraverti, ses véritables partenaires sont donc les juges extérieurs — Te et Fe, les fonctions qui apportent une correction extérieure. Cliquez sur une alimentatrice pour voir ce qui converge.","ni.zoneC.unstableDefault":"Couplage instable : une perception alimentant une perception, sans que rien ne juge l'une ou l'autre.","ni.zoneD.canvasAria":"Le moteur de régression Ni : des observations éparses, une trajectoire ajustée avec une enveloppe de variance, et une construction qui peut être orientée d'avant en arrière le long de l'axe du temps par pointage ou glissement","ni.zoneD.heading":"Le moteur de régression","ni.zoneD.kicker":"Zone D · le moteur de régression","ni.zoneD.lede":"Ni identifie une trajectoire prédictive à travers des entrées bruitées et multidimensionnelles, puis la projette vers l'avant dans le temps. Ce laboratoire expose l'état en direct du moteur — stress, plaisir, confiance, perte — et les cinq façons dont une journée peut le traiter. Déclenchez un scénario et regardez la télémétrie répondre.","ni.zoneD.ledeHintCoarse":"Appuyez et faites glisser de gauche à droite dans la chambre à tout moment pour diriger la construction à travers le temps vous-même.","ni.zoneD.ledeHintFine":"Survolez la chambre à tout moment pour diriger le construit à travers le temps vous-même.","ni.zoneE.lede":"Des motifs sauvages — comment Ni se manifeste dans la vie quotidienne."};export{e as _meta,n as default};
